const styles=new CSSStyleSheet;styles.replaceSync("/**\n * Copyright 2019 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\nh1 {\n  font-weight: normal;\n}\n\n.css-overview-start-view {\n  padding: 24px;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  background-color: var(--sys-color-cdt-base-container);\n  overflow: auto;\n}\n\n.start-capture-wrapper {\n  width: fit-content;\n}\n\n.preview-feature {\n  padding: 12px 16px;\n  border: 1px solid var(--color-details-hairline);\n  color: var(--color-text-primary);\n  font-size: 13px;\n  line-height: 20px;\n  border-radius: 12px;\n  margin: 42px 0;\n  letter-spacing: 0.01em;\n}\n\n.preview-header {\n  color: var(--color-primary-old);\n  font-size: 13px;\n  line-height: 20px;\n  letter-spacing: 0.01em;\n  margin: 9px 0 14px;\n}\n\n.preview-icon {\n  vertical-align: middle;\n}\n\n.feedback-prompt {\n  margin-bottom: 24px;\n}\n\n.feedback-prompt .devtools-link {\n  color: -webkit-link;\n  cursor: pointer;\n  text-decoration: underline;\n}\n\n.resources {\n  display: flex;\n  flex-direction: row;\n}\n\n.thumbnail-wrapper {\n  width: 144px;\n  height: 92px;\n  margin-right: 20px;\n}\n\n.video-doc-header {\n  font-size: 13px;\n  line-height: 20px;\n  letter-spacing: 0.04em;\n  color: var(--color-text-primary);\n  margin-bottom: 2px;\n}\n\ndevtools-feedback-button {\n  align-self: flex-end;\n}\n\n.resources .devtools-link {\n  font-size: 14px;\n  line-height: 22px;\n  letter-spacing: 0.04em;\n  text-decoration-line: underline;\n  color: var(--color-primary-old);\n}\n\n/*# sourceURL=cssOverviewStartView.css */\n");export default styles;